import { jsx as _jsx } from "react/jsx-runtime";
import { describe, it, expect } from "vitest";
import { screen, render } from "@testing-library/react";
import { Attribute } from "../Attribute";
import { Chip } from "@mui/material";
import { ExampleIcon } from "../../ExampleIcon";
describe("Rapid7 Attribute", () => {
    it("Should render the Attribute with the correct label and content string", () => {
        render(_jsx(Attribute, { content: "Jill Smith", label: "User" }));
        expect(screen.getByText("Jill Smith")).toBeInTheDocument();
        expect(screen.getByText("User")).toBeInTheDocument();
    });
    it("Should render the Attribute with the correct label and tag content", () => {
        render(_jsx(Attribute, { content: _jsx(Chip, { label: "Status" }), label: "User" }));
        expect(screen.getByText("User")).toBeInTheDocument();
        expect(screen.getByText("Status")).toBeInTheDocument();
    });
    it("Should render the Attribute with the correct label, icon and content", () => {
        render(_jsx(Attribute, { content: "Icon", icon: ExampleIcon, label: "User" }));
        expect(screen.getByText("User")).toBeInTheDocument();
        expect(screen.getByText("Icon")).toBeInTheDocument();
        expect(screen.getByTestId("example-icon")).toBeInTheDocument();
    });
});
